function swapAdjectives(sentence) {
  // 1. Extract Noun Phrase: Identify the noun phrase containing adjectives (e.g., "green trees").
  const regex = /(\b\w+(?:\s+\w+)*)\s*(?:adjective1\s*)adjective2+/; // Adjust regex for more complex cases if needed
  const match = sentence.match(regex);
  if (!match) return sentence; // Handle sentences without clear adjective patterns

  const nounPhrase = match[1]; // Extract the identified noun phrase
  const originalAdjectives = nounPhrase.split(/\s+/).filter(word => word.toLowerCase() !== nounPhrase.split(/\s/).pop().toLowerCase()); // Filter out the noun itself

  // 2. Reverse and Reconstruct:
  const reorderedAdjectives = originalAdjectives.reverse().join(" ");
  const swappedSentence = sentence.replace(nounPhrase, `${reorderedAdjectives} ${nounPhrase.split(/\s/).pop()}`);

  return swappedSentence;
}

// Example Usage:
const sentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(sentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park 
