const axios = require('axios'); // Assuming you have axios for HTTP requests

/**
 * Posts a message to a specified Slack channel using the API.
 *
 * @param {string} text  - The message content to send.
 * @param {string} channel - The Slack channel ID (e.g., 'C1234567890ABC') to post to.
 * @param {object} [slackApiToken] - An object with a 'token' property containing your valid Slack API token. 
 *                                   Essential for authentication. **(Mandatory)**
 * @returns {Promise<object>} - Resolves with the Slack API's response data on success, 
 *                            rejects with an error on failure.
 */
async function sendMessageToSlack(text, channel, slackApiToken) {
  if (!slackApiToken || !slackApiToken.token) {
    return Promise.reject(new Error("Missing required 'slackApiToken.token' for authentication."));
  }

  const apiUrl = `https://slack.com/api/chat.postMessage`;
  const payload = {
    channel: channel,
    text: text,
    // Add optional parameters like thread_ts, username, etc. for richer messages
  };

  try {
    const response = await axios.post(apiUrl, payload, {
      headers: {
        Authorization: `Bearer ${slackApiToken.token}` //  Authentication header
      }
    });
    return response.data; // Return Slack API's response (contains message details, etc.)
  } catch (error) {
    console.error("Slack API Error:", error);
    return Promise.reject(error); 
  }
}

// Example Usage:
const mySlackToken = { token: 'YOUR_ACTUAL_SLACK_API_TOKEN' }; // Replace with your token
sendMessageToSlack("Hello from JavaScript!", "general", mySlackToken)
  .then(result => console.log("Message posted successfully:", result))
  .catch(err => console.error("Posting failed:", err));
```

