async function postToSlack(text, channelId, slackApiToken) {
  // **Helpfulness (High):** Clearly outlines the function's purpose and parameters.
  /**
   * Posts a given text message to a specified Slack channel using the provided API token.
   *
   * @param {string} text - The message content to be posted.
   * @param {string} channelId - The unique ID of the Slack channel.
   * @param {string} slackApiToken - Your valid Slack API token with necessary permissions.
   * @returns {Promise<Object>} - Resolves with the Slack API response (success/error details) upon completion.
   */

  try {
    const response = await fetch(`https://slack.com/api/chat.postMessage`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${slackApiToken}` // **Verbosity: Explaining Authentication**
      },
      body: JSON.stringify({
        channel: channelId,
        text: text
      })
    });

    // **Helpfulness & Verbosity: Robust Error Handling & Feedback**
    const data = await response.json();
    if (data.ok) {
      console.log(`Message posted successfully to channel ${channelId}:`, data.message.text); 
      return data; // Return success data for clarity
    } else {
      console.error(`Error posting to Slack:`, data.error);
      throw new Error(data.error); // Re-throw for better error management
    }
  } catch (error) {
    console.error('Critical Slack API Error:', error);
    throw error; // Propagate error for handling elsewhere
  }
}
