import Foundation

func generateSportComparison(userChoice: String) -> [[String]] {
    var comparisonData: [[String]] = [] // Our data structure (Excel-like rows/columns)

    // Header Row (Fixed)
    comparisonData.append(["Factor", "Skiing", "Snowboarding"])

    // Data Population using Conditional Logic
    let factors = [
        "Speed": userChoice == "skiing" ? "High (especially downhill)" : "Moderate to High (terrain dependent)",
        "Difficulty": userChoice == "skiing" ? "Generally moderate initial learning curve, advanced techniques steeper" : "Steeper initial learning curve, but progressive styles",
        "Style": userChoice == "skiing" ? "Classic, graceful, versatile" : "Fluid, edgy, freeride emphasis",
        "Learning Curve": userChoice == "skiing" ? "Relatively quicker basics, mastery takes time" : "Initial hurdle, but rewarding progression",
        "Terrain Variety": userChoice == "skiing" ? "Excellent adaptability to groomed runs, backcountry, parks" : "Strong in powder, parks, and off-piste, adaptable but less groomed focus",
        "Trick Opportunities": userChoice == "skiing" ? "Growing freestyle scene, but less specialized" : "Highly conducive to tricks and freestyle maneuvers"
    ]

    // Populate Data Rows (Formatted for Excel Clarity)
    for (factor, value) in factors {
        comparisonData.append([factor, value])
    }

    return comparisonData
}

// User Input & Output (Simulated Excel-Ready Format)
