using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Or your preferred JSON serialization library

public class RestServiceWrapper<T> where T : class
{
    private readonly string _baseUrl;
    private readonly string _authTokenHeaderName = "Authorization";
    private readonly Func<Task<string>> _getTokenAsync; // Delegate for obtaining fresh auth tokens

    public RestServiceWrapper(string baseUrl, Func<Task<string>> getTokenAsync)
    {
        _baseUrl = baseUrl;
        _getTokenAsync = getTokenAsync;
    }

    protected virtual async Task<HttpResponseMessage> SendRequestInternal(HttpMethod method, string relativeUrl, object content = null, Dictionary<string, string> additionalHeaders = null)
    {
        using (var client = new HttpClient())
        {
            // 1. Obtain and attach authentication token
            string authToken = await _getTokenAsync();
            client.DefaultRequestHeaders.Add(_authTokenHeaderName, $"Bearer {authToken}"); // Common Bearer token format

            if (additionalHeaders != null)
                foreach (var header in additionalHeaders)
                    client.DefaultRequestHeaders.Add(header.Key, header.Value);

            // 2. Build and execute the request
            var request = new HttpRequestMessage(method, $"{_baseUrl}{relativeUrl}");
            if (content != null)
                request.Content = new StringContent(JsonConvert.SerializeObject(content), System.Text.Encoding.UTF8, "application/json");

            return await client.SendAsync(request);
        }
    }

    // Generic methods leveraging SendRequestInternal for common operations:
    public async Task<T> GetAsync<T>(string relativeUrl) where T : class
    {
        var response = await SendRequestInternal(HttpMethod.Get, relativeUrl);
        return await HandleResponse<T>(response);
    }

    public async Task<T> PostAsync<T>(string relativeUrl, object data) where T : class
    {
        var response = await SendRequestInternal(HttpMethod.Post, relativeUrl, data);
