import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { Role } from './user.entity'; // Assuming User entity has a Role enum

const PERMISSIONS = ['READ_DATA', 'CREATE_DATA', 'UPDATE_DATA', 'DELETE_DATA', 'ADMIN'];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles specified, allow access

    const request = context.switchToHttp().getRequest();
    const user = request.user; 
    if (!user || !user.role) throw new UnauthorizedException('User not authenticated');

    return requiredRoles.some(role => user.role === role || PERMISSIONS.includes(user.role) && PERMISSIONS.some(perm => requiredRoles.includes(perm)));
  }
}
```

**Explanation (for context, NOT part of `index.js`):**

1. **`PERMISSIONS` Array:**  Defines a central list of standardized permission names for the application's authorization logic.
2. **`RolesGuard`:**
   - Decorated with `@Injectable` for dependency injection.
   - Uses `Reflector` to fetch `roles` metadata defined on controllers/methods requiring specific permissions.
   - Retrieves user role from the request (assuming authentication setup provides `user.role`).
   - **Authorization Logic:**  Checks if:
     -  The user's role *directly matches* any required role OR
     - The user has a broader role (like 'ADMIN') that encompasses at least one of the required permissions.
   - Throws `UnauthorizedException` if access is denied. 

**Integration into NestJS:**

- Apply `@UseGuards(RolesGuard)` decorator to NestJS routes, controllers, or methods where you want role-based access control.
- In route decorators, specify  `roles: [Role.ADMIN, Role.WRITER]`  (or

```typescript
import { Injectable } from '@nestjs/common';
import { AuthGuard, CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { UserService } from './user.service';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService, private userService: UserService) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles restriction

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user) throw new UnauthorizedException('Unauthorized');

    return this.userService.userHasRoles(user.id, requiredRoles);
  }
}

// Example Permission Structure (in a centralized config or service)
export const PERMISSIONS = [
  'READ_USERS', 'CREATE_USERS', 'UPDATE_USERS', 'DELETE_USERS',
  'READ_PRODUCTS', 'CREATE_PRODUCTS', 'MANAGE_ inventario', 'ANALYTICS_ACCESS',
  // ... more permissions
];
```

**Explanation (for context, NOT part of `index.js`):**

1. **`RolesGuard`:** A custom authorization guard using `@nestjs/common` decorators.
   - Retrieves `requiredRoles` metadata from decorated controllers/actions using `@Roles(...)`.
   - Checks for authenticated user (`request.user`).
   - Calls `userService.userHasRoles()` to verify if the user possesses any of the needed roles against database data. Throws `UnauthorizedException` if not.

2. **`PERMISSIONS` Array:**  A示例结构定义了应用程序中的权限名称。这应该 быть в отдельном конфигурационном файле или сервисе в реальном приложении для динамической настройки и расширения.
3. **Integration:** Within your NestJS controllers/routes, apply `@UseGuards(RolesGuard)`  alongside  `@Roles(requiredRoleArray)`  to enforce access control based on this logic.


This setup allows for fine-grained permission management and integrates seamlessly with NestJS and TypeORM for user role data persistence.

```javascript
import { Injectable } from '@nestjs/common';
import { AuthGuard, ExecutionContext, Reflector } from '@nestjs/common';
import { PrismaService } from './prisma.service';
import { Prisma } from '@prisma/client';

interface Permission {
  name: string;
}

const PERMISSIONS = [
  { name: 'READ_USERS' },
  { name: 'CREATE_USERS' },
  { name: 'UPDATE_USERS' },
  { name: 'DELETE_USERS' },
  // ... add more permissions similarly
];

@Injectable()
export class RolesAuthGuard extends AuthGuard {
  constructor(private prisma: PrismaService, private reflector: Reflector) {}

  asynccanActivate(context: ExecutionContext): Promise<boolean | undefined> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public endpoint

    const request = context.switchToHttp().getRequest();
    const user = request.user as Prisma.User;
    const userRoles = await this.prisma.userRole.findMany({
      where: { userId: user.id },
      select: { roleId: true },
    });
    const allowedRoles = await this.prisma.role.findMany({
      where: { id: { in: userRoles.map((r) => r.roleId) } },
      select: { name: true },
    });
    return requiredRoles.some((role) => allowedRoles.some((userRole) => userRole.name === role));
  }
}

export const hasPermission = (permission: Permission['name']) => (
  target,
  propertyKey,
  descriptor
) => {
  const method = descriptor.value;
  descriptor.value = async (...args) => {
    const request = args[0].req;
    const user = request.user as Prisma.User;
    const hasAccess = await this.prisma.userRole.findFirst({
      where: { userId: user.id, roleId: { permissions: { some: { name: permission.name } } } },
    });
    if (!hasAccess) throw new Error('Insufficient permissions');
    return method.apply(this, args);
  };
  return descriptor;

