/**
 * Searches for a place name in a specified column and retrieves latitude/longitude, storing them in designated columns.
 *
 * @param {string} sheetName The name of the Google Sheet containing the data.
 * @param {string} placeNameColumn The header of the column with place names to search (e.g., "Place").
 * @param {string} latColumn The header of the column to store latitudes (e.g., "Latitude").
 * @param {string} lngColumn The header of the column to store longitudes (e.g., "Longitude").
 * @param {function(string): Promise<GeocoderResult>} geocoderFunction  A custom function (see explanation below) for enhanced geocoding accuracy/handling. Defaults to Google Maps Geocoding API.
 */
function fetchLatLngFromPlaceNames(sheetName, placeNameColumn, latColumn, lngColumn, geocoderFunction = googleMapsGeocode) {

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();

  // Iterate through each row (assuming headers are in the first row)
  for (let row = 1; row < values.length; row++) {
    const placeName = values[row][placeNameColumn - 1]; // Adjust column index (0-based)
    if (placeName) {
      (async () => {
        try {
          const geocodingResult = await geocoderFunction(placeName); 
          const lat = geocodingResult.geometry.location.lat();
          const lng = geocodingResult.geometry.location.lng();

          // Update sheet cells
          sheet.getRange(row + 1, latColumn).setValue(lat);  // +1 for header row
          sheet.getRange(row + 1, lngColumn).setValue(lng);
        } catch (error) {
          console.error(`Error geocoding "${placeName}": ${error}`);
          // Handle errors gracefully (e.g., log, set an error marker in sheet)
        }
      })(); 
    }
  }
}

