function extractNestedValue(options, dotNotationKey) {
  // Split the dot notation into individual keys for traversal
  const keys = dotNotationKey.split('.');
  let currentEntry = options;

  // Traverse the nested structure, updating 'currentEntry' at each step
  for (const key of keys) {
    if (typeof currentEntry === 'object' && currentEntry !== null && key in currentEntry) {
      currentEntry = currentEntry[key]; 
    } else {
      // Key not found along the path, return undefined (handle missing keys gracefully)
      return undefined; 
    }
  }

  // Return the final value found, representing the matched nested entry
  return currentEntry;
}
```

