// extractStructField extracts Avro Schema definition for a single struct field
func extractStructField(field *ast.Field, packageName string) *schema.Field {
	fieldName := field.Names[0].Name
	fieldType := field.Type

	// Handle basic types and arrays/maps with type assertions
	var avroType string
	switch t := fieldType.(type) {
	case *ast.Ident:
		// Primitive types (string, int, bool, etc.)
		avroType = avroTypeFromGoType(t.String())
	case *ast.StarExpr: // Pointer, treat as nullable
		avroType = fmt.Sprintf("{%s?*}", avroTypeFromGoType(t.X.(*ast.Ident).String()))
	case *ast.MapType:
		avroType = fmt.Sprintf("map<%s,%s>", avroTypeFromGoType(t.Key.(*ast.Ident).String()), avroTypeFromGoType(t.Value.(*ast.Ident).String()))
	case *ast.ArrayType:
		avroType = fmt.Sprintf("[%s]", avroTypeFromGoType(t.Elt.(*ast.Ident).String()))
	default:
		log.Printf("WARNING: Unhandled type in field %s: %T, falling back to string", fieldName, fieldType)
		avroType = "string" // Handle complex types conservatively for now
	}

	// Optional: Incorporate documentation or tags for Avro doc and default values later

	return &schema.Field{
		Name:      fieldName,
		Type:      avroType,
