<!DOCTYPE html>
<html>
<head>
  <title>Desktop Background Viewer</title>
  <style>
    #backgroundImageContainer {
      position: relative;
      width: 500px; /* Adjust as needed for desired display size */
      height: 300px; /* Adjust as needed */
      overflow: hidden; /* Ensure image doesn't overflow container */
    }

    #displayImage {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      object-fit: cover; /* Maintain aspect ratio */
    }
  </style>
</head>
<body>

  <h1>Display Your Desktop Background</h1>

  <button id="showDesktopBG">Show Desktop Background</button>

  <div id="backgroundImageContainer">
    <img id="displayImage" src="" alt="User's Desktop Background"> </div>

  <script>
    const showDesktopBGButton = document.getElementById('showDesktopBG');
    const backgroundContainer = document.getElementById('backgroundImageContainer');
    const displayImage = document.getElementById('displayImage');

    showDesktopBGButton.addEventListener('click', async () => {
      try {
        // **Cross-browser approach using File System Access API (modern browsers)**
        const toegang = await window.showOpenFilePicker({
          types: [{ description: 'Images', extensions: ['jpg', 'jpeg', 'png', 'gif'] }],
          multiple: false // Only allow selecting one file (desktop background)
        });
        const fileHandle = toegang[0]; 
        const stream = await fileHandle.getFile();
        const reader = new FileReader();

        reader.onload = (event) => {
          displayImage.src = event.target.result;
          backgroundContainer.style.display = 'block'; // Show container
        };
        reader.readAsDataURL(stream); 

      } catch (err) {
        console.error("Error accessing desktop background:", err);
        alert("Permission denied or browser incompatibility. This feature requires modern browser support for File System Access API.");
      }
    });
  </script>

</body>
</html>
