            // 3. Map Spectrum to Bar Heights
            for (int i = 0; i < bars.Length && i < spectrum.Length; i++)
            {
                float normalizedFrequency = spectrum[i] / Mathf.Max(spectrum); // Normalize for consistent scaling
                bars[i].fillAmount = normalizedFrequency * barHeightMultiplier; // Update bar height
            }

            yield return null; // Yield for smoother updates
        }
