        // 2. Extract Required Information (with clarity and verbosity)

        Console.WriteLine($"Total Visas Issued in 2021: {data.VisasIssued}");

        // Top Countries - Order by count for clarity
        var sortedTopCountries = data.TopCountries.OrderByDescending(x => x.Value).Take(3); // Get top 3
