#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *argvToCString(int argc, char **argv) {
    // 1. Calculate Total String Length:
    size_t totalLength = 0;
    for (int i = 0; i < argc; ++i) {
        totalLength += strlen(argv[i]) + 1; // Add 1 for separating spaces
    }

    // 2. Allocate Memory for Combined String:
    char *combinedString = malloc(totalLength);
    if (combinedString == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(1); // Handle memory error
    }

    // 3. Construct the C-String:
    char *currentPos = combinedString;
    for (int i = 0; i < argc; ++i) {
        strcpy(currentPos, argv[i]);  // Copy each argument
        currentPos += strlen(argv[i]);
        *currentPos++ = ' ';      // Append space separator
    }
    *--currentPos = '\0'; // Null-terminate the final string

    return combinedString;
}

int main(int argc, char **argv) {
    char *combinedArgs = argvToCString(argc, argv);
    printf("Combined argv as C-string: %s\n", combinedArgs);
    free(combinedArgs); // Remember to free allocated memory
    return 0;
}
```

