// 2. Construct SQL Query with GROUP BY & HAVING for Loyalty Identification
$sql = "
    SELECT customer_id, product_name
    FROM orders
    WHERE product_name = 'specific_product_name'  -- Replace with the target product
    GROUP BY customer_id
    HAVING COUNT(DISTINCT order_date) >= 3 
        AND DATE_PART('week', order_date) BETWEEN DATE_TRUNC('week', CURRENT_DATE - INTERVAL '6 week') AND CURRENT_DATE  -- Filter within last 6 weeks
";

