<?php

// Assuming your transaction data is stored in a MySQL table named 'orders' with columns:
//  - customer_id (INT): Unique identifier for each customer
//  - product_name (VARCHAR): Name of the purchased product
//  - order_date (DATE): Date of the transaction

// Product to target for loyalty analysis (e.g., "Latte")
$targetProduct = "Latte";

// Establish database connection (replace with your credentials)
$conn = new mysqli("localhost", "username", "password", "coffee_shop_db");
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// SQL query using GROUP BY and HAVING for refined customer identification
$sql = "
    SELECT customer_id, COUNT(*) AS latte_purchases
    FROM orders
    WHERE product_name = '$targetProduct'
    GROUP BY customer_id
    HAVING COUNT(*) >= 3 
        AND DATE_PART('week', order_date) IN (DATE_TRUNC('week', CURRENT_DATE) - INTERVAL '6 week', DATE_TRUNC('week', CURRENT_DATE)) 
    ORDER BY latte_purchases DESC;
";

$result = $conn->query($sql);

if ($result->num_rows > 0) {
    echo "<h2>Devoted Latte Customers (past 6 weeks):</h2>";
    echo "<table border='1'>
          <tr><th>Customer ID</th><th>Latte Purchases</th></tr>";
    // Present data in a structured table format for clarity
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["customer_id"] . "</td><td>" . $row["latte_purchases"] . "</td></tr>";
    }
    echo "</table>";
} else {
    echo "No customers met the criteria (3+ Latte purchases in the last 6 weeks)";
}

$conn->close();

?>
```

