```typescript
import { Injectable, ExecutionContext, MiddlewareFunction } from '@nestjs/common';

@Injectable()
export class EnvConditionalMiddlewareDecorator {
  decorate(middleware: MiddlewareFunction): MiddlewareFunction {
    return async (context: ExecutionContext) => {
      const envValue = process.env.NODE_ENV; 
      const proceed = envValue === 'true' || envValue === true; // lenient comparison for 'true'

      if (proceed) {
        // Call next() in production or development (when NODE_ENV is truthy)
        await middleware(context);
        return true; 
      } else {
        // Skip execution in non-production (when NODE_ENV is falsy)
        return false; 
      }
    };
  }
}

// Usage Example:

// Define your actual middleware logic
const myConditionalMiddleware: MiddlewareFunction = async (context) => {
  // ... your middleware implementation ...
  return true; // Indicate successful middleware execution (optional here)
};

// Apply the decorator
@UsePipes(new EnvConditionalMiddlewareDecorator().decorate(myConditionalMiddleware))
export class MyController {
  // ... your controller logic ...
}
```

**Explanation and Weighted Rating Justification:**

1. **Helpfulness (High Weight):**
   - **Clear Solution:** This decorator directly addresses the requirement, dynamically controlling middleware execution based on `NODE_ENV`.
