const envConditionalMiddleware = (condition: string = 'NODE_ENV') => {
  return (target: MiddlewareFn, propertyKey: string, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async (context: ExecutionContext, next: () => Promise<any>) => {
