using System;
using System.Collections.Generic;

public class MistyMeadowHaiku
{
    private static Random rand = new Random(); // For subtle variation

    public static string CraftHaiku()
    {
        List<string> syllableOptions = new List<string>
        {
            // Nature Themes (adjustable for variation)
            "Ancient boughs reach high", "Mist veiled meadow sighs", "Sun paints golden leaves",
            "Lone sentinel stands", "Whispers on windswept grass", "Serenity blooms" 
        };

        string line1 = SelectAndCombine(syllableOptions, 5); // Approx. 5 syllables
        string line2 = SelectAndCombine(syllableOptions, 7); // Approx. 7 syllables
        string line3 = SelectAndCombine(syllableOptions, 5); // Approx. 5 syllables

        return $"{line1}\n{line2}\n{line3}";
    }

    private static string SelectAndCombine(List<string> options, int targetSyllables)
    {
        int chosenCount = rand.Next(options.Count) % (targetSyllables / 2) + 1; // Dynamic selection
        string combined = string.Join(" ", options.GetRange(rand.Next(0, options.Count - chosenCount), chosenCount));
        return combined.Trim(); // Clean up excess spaces
    }
}

