   async function manageMediaAccess(cameraOn, micOn) {
     try {
       const constraints = { video: cameraOn, audio: micOn }; // Define desired access
       const stream = await navigator.mediaDevices.getUserMedia(constraints); 

       // Handle Stream Acquisition Success:
       if (stream) {
         console.log(`Successfully accessed ${cameraOn ? 'camera' : '' } and ${micOn ? 'microphone' : ''}`);
         //  Integrate stream into elements (e.g., <video> for camera, <audio> for mic feedback)
         //  ... your logic to utilize the stream ...
         return stream; // Return for further management (stopping, etc.)
       } else {
         console.error("User denied media access. Proceeding without.");
       }
     } catch (err) {
       console.error("Error accessing media:", err);
     }
   }

   // Usage Examples:
   manageMediaAccess(true, true) // Open both
     .then(stream => { 
       //  Manage stream lifecycle here (e.g., stop when needed)
     });

   manageMediaAccess(false, true) // Only microphone
   ```

   - **Explanation:**
     - **Permissions First:**  Relies on `navigator.mediaDevices.getUserMedia()` which *always* prompts the user for permission, ensuring ethical handling.
     - **Flexibility:**  `constraints` lets you selectively enable camera (`video: true`) or microphone (`audio: true`).
     - **Stream Management:** The returned stream object is crucial for controlling media flow and cleanup later.

