import React, { useState, useEffect } from 'react';
import Combobox from 'downshift/Combobox';
import { searchEmails } from './emailService'; // Assuming your async function resides here

interface EmailOption {
  value: string;
  label: string; // Display name for the autocomplete suggestion
}

const AutocompleteEmailInput: React.FC = () => {
  const [emails, setEmails] = useState<EmailOption[]>([]);
  const [inputValue, setInputValue] = useState('');

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
    // Trigger email search on input change with debounce for performance
    searchEmails(event.target.value)
      .then(results => setEmails(results))
      .catch(error => console.error('Error fetching emails:', error)); 
  };

  return (
    <Combobox
      value={inputValue}
      onChange={setInputValue}
      itemToString={(item: EmailOption) => item.label} // Display label for suggestions
      onInputValueChange={handleInputChange} // Capture input for search
      getLabelProps={() => ({ style: { fontWeight: 'bold' } })} // Optional styling
      items={emails}
      renderInput={(props) => (
        <input 
          {...props} 
          type="email" 
          placeholder="Enter email address..." 
          style={{ padding: '8px', border: '1px solid #ccc' }} 
        />
      )}
      renderSelectedItem={(selectedItem) => (
        <div style={{ fontWeight: 'bold', color: 'blue' }}>{selectedItem.label}</div> // Highlight selected item
      )}
    />
  );
};

export default AutocompleteEmailInput;
```

