import React, { useState, useEffect } from 'react';
import Combobox from 'downshift/Combobox';
import { searchEmails } from './emailService'; // Assuming your async function is here

interface EmailOption {
  value: string; // Complete email address
  label: string; // Displayed suggestion (e.g., first part of email)
}

const AutocompleteEmailInput: React.FC = () => {
  const [inputValue, setInputValue] = useState('');
  const [suggestions, setSuggestions] = useState<EmailOption[]>([]);

  const handleInputChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
    const prefix = event.target.value;
    try {
      const fetchedEmails = await searchEmails(prefix);
      setSuggestions(fetchedEmails.map(email => ({ value: email, label: email }))); // Simple mapping for demo, adapt as needed
    } catch (error) {
      console.error('Error fetching emails:', error);
      setSuggestions([]); // Handle errors gracefully
    }
  };

  return (
    <Combobox
      value={inputValue}
      onChange={setInputValue}
      onInputValueChange={handleInputChange} // Trigger search on every input change
      itemToString={(item: EmailOption) => item.label} // Display suggestion's label
      renderInput={(props) => (
        <input {...props} type="email" placeholder="Enter email address..." />
      )}
      suggestions={suggestions}
      selectedItemRenderer={(item) => item.value} // Show full email on selection
      // ...additional Downshift customization options as desired...
    />
  );
};

export default AutocompleteEmailInput;
