import Foundation

func optimisticRearrange(_ phrase: String) -> String {
    // 1. Extract & Prioritize Positive Vibes:
    let positivityKeywords = ["joy", "hope", "love", "grate", "thank", "bless"].compactMap { keyword in
        phrase.lowercased().contains(keyword) ? keyword : nil
    }
    var rearrangedLetters = phrase.filter { !$0.isWhitespace }.sorted()

    // 2.  Strategic Insertion for Optimism:
    for keyword in positivityKeywords {
        if let index = rearrangedLetters.firstIndex(where: { $0 == keyword.first! }) {
            rearrangedLetters.swapAt(index, 0) // Move keyword to beginning
        }
    }

    // 3.  Gratitude Emphasis:
    let gratitudeSection = phrase.lowercased().components(separatedBy: " ").filter { $0.hasPrefix("thank") || $0.hasPrefix("grate") }.joined(separator: " ")
    rearrangedLetters.insert(contentsOf: gratitudeSection.filter { !$0.isWhitespace }.sorted(), at: rearrangedLetters.startIndex)

    // 4. Construct & Enhance:
    let structuredPhrase = String(rearrangedLetters)
    return "Embrace \(structuredPhrase) with a heart full of gratitude and hope!" 
}

