import * as Chart from 'chart.js'; // Assuming Chart.js for visualization

// Function to generate the bar chart from user input
async function createBarChartFromInput(): Promise<void> {
  try {
    // 1. User Input (Data Acquisition - Verbosity: High)
    console.log("Please provide your dataset as comma-separated values (CSV) with labels and corresponding values, e.g., 'CategoryA,15, CategoryB,28, CategoryC,12...'");
    const dataString = await prompt("Enter your dataset in CSV format:");

    // 2. Data Processing & Transformation (Core Logic - Helpfulness: High)
    const dataArray = dataString.split(',').reduce((acc, item) => {
      const [label, value] = item.split(',');
      acc.labels.push(label.trim());
      acc.datasets[0].data.push(parseInt(value.trim(), 10)); // Parse as integers
      return acc;
    }, { labels: [], datasets: [{ data: [] }] });

    // 3. Chart.js Setup & Rendering (Visualization - Helpfulness: High, Verbosity: Medium)
    const ctx = document.getElementById('myChart') as HTMLCanvasElement; // Assuming canvas with id 'myChart'
    new Chart(ctx, {
      type: 'bar',
      data: {
        labels: dataArray.labels,
        datasets: dataArray.datasets
      },
      options: {
        scales: {
          y: {
            beginAtZero: true // Ensure y-axis starts at zero for clarity
          }
        }
      }
    });
    console.log("BarChart generated successfully!");
  } catch (error) {
    console.error("Error creating chart:", error);
  }
}

// Initiate chart creation on page load (or any suitable trigger)
window.addEventListener('load', createBarChartFromInput);
```

