import React, { useRef, useEffect } from 'react';

const RemoveWidowCleaner = ({ children }) => {
  const paragraphRef = useRef(null);

  useEffect(() => {
    // Function to handle widow removal using CSS manipulation
    const cleanWidows = () => {
      if (paragraphRef.current) {
        const paragraphs = paragraphRef.current.querySelectorAll('p');
        paragraphs.forEach(p => {
          // Logic adapted from common widow prevention techniques:
          // 1. Check for single-line paragraphs at the end with insufficient space
          //    below (adjust padding/margin values as needed for your styling)
          if (p.textContent.trim().length < 30 && getComputedStyle(p).getPropertyValue('marginBottom') <= '5px') {
            p.style.marginBottom = '1em'; // Increase marginBottom to create separation
          }
        });
      }
    };

    // Execute widow cleaning on component mount and after every render
    cleanWidows();
    const observer = new MutationObserver(cleanWidows);
    observer.observe(paragraphRef.current, { childList: true, subtree: true });

    // Cleanup observer on unmount
    return () => observer.disconnect();
  }, []); // Empty dependency array ensures re-execution on every render

  return <div ref={paragraphRef}>{children}</div>;
};

export default RemoveWidowCleaner;
```

