      if (lastLine && lastLine.textContent.trim().length < threshold /* Customize threshold here */) { 
        // Strategies for removal:
        // 1. Simple Removal (most direct):
        paragraph.removeChild(lastLine); 
        // 2. Merge with Previous:  (Preserve flow better)
