        //    and append lastLine's content to it while adjusting styling as needed.
        // 3. CSS-Based Solution:  (Potentially more elegant)
        //    Apply targeted CSS rules within your stylesheet to intelligently handle widows 
        //    based on line height, padding, etc., avoiding direct DOM manipulation.

        // Choose and implement your preferred strategy here (comments suggest options)
      }
    });
  }, [selector]); // Re-run on selector changes

  return null; // Utility returns nothing, modifies DOM directly
};

