import { useEffect, useRef } from 'react';

const useRemoveWidows = (containerRef) => {
  const prevContentRef = useRef(null); // Store previous rendered content for comparison

  useEffect(() => {
    const handleWindowRemoval = () => {
      // 1. Get Container Content & Normalize:
      const containerText = containerRef.current?.textContent || '';
      const lines = containerText.split('\n');

      // 2. Identify Widow Lines (Last line with insufficient context):
      const widowThreshold = 2; // Adjust this value for sensitivity (e.g., words or characters)
      const widows = lines.filter((line, index) => index === lines.length - 1 && line.trim().length < widowThreshold);

      // 3. Merge with Previous if Applicable:
      if (prevContentRef.current && widows.length) {
        const prevLastLine = prevContentRef.current.split('\n').slice(-1)[0].trim();
        widows.forEach(widow => {
          const merged = `${prevLastLine} ${widow.trim()}`; // Simple merge, adapt logic as needed
          containerRef.current.textContent = containerText.replace(widow, merged).trim();
        });
      }

      prevContentRef.current = containerText; // Update for next render comparison
    };

    handleWindowRemoval(); // Initial check on mount
