// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor(options = {}) {
    this.client = redis.createClient(options);

    // Handle Redis client errors in the console
    this.client.on('error', (err) => console.error(`Redis Client Error: ${err}`));
  }

  isAlive() {
    return new Promise((resolve) => {
      this.client.ping((err, reply) => {
        resolve(!err && reply === 'PONG'); 
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err); // Handle Redis errors during retrieval
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, durationInSeconds) {
    return new Promise((resolve, reject) => {
      this.client.setex(key, durationInSeconds, value, (err) => {
        if (err) {
          reject(err);
        } else {
          resolve({ success: true }); // Indicate successful set operation
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, deletedCount) => {
        if (err) {
          reject(err);
        } else {
          resolve(deletedCount > 0); // Resolve with true if deletion successful
        }
      });
    });
  }
}

// Create and export an instance
const redisClient = new RedisClient({ /* Your Redis connection options here */ });
module.exports = redisClient;
