        if (err) {
          resolve(false); // Connection issue
        } else {
          resolve(true); // Successful ping
        }
      });
    });
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error(`Error retrieving value for key ${key}:`, err);
      throw err; // Re-throw for higher-level handling
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.SET(key, value, 'EX', duration); 
      console.log(`Value set for key ${key} with expiration in ${duration} seconds`);
    } catch (err) {
      console.error(`Error setting value for key ${key}:`, err);
      throw err; 
    }
  }

  async del(key) {
    try {
      const deleted = await this.client.DEL(key);
      if (deleted > 0) {
        console.log(`Key ${key} successfully deleted`);
      } else {
        console.warn(`Key ${key} not found (or deletion failed)`);
      }
    } catch (err) {
      console.error(`Error deleting key ${key}:`, err);
      throw err; 
    }
  }
}

// Create and export an instance
const redisClient = new RedisClient({ /* Your Redis connection options here */ });
module.exports = redisClient;
