// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor(options = {}) {
    this.client = redis.createClient(options);
    this.client.on('error', (err) => console.error('Redis Client Error:', err)); // Display errors in console
  }

  isAlive() {
    return new Promise((resolve) => {
      this.client.ping((err, reply) => {
        resolve(!err && reply === 'PONG'); 
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) reject(err);
        resolve(value);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.SET(key, value, 'EX', duration, (err) => {
        if (err) reject(err);
        resolve(); // Resolve on successful set, even without direct value retrieval
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, deletedCount) => {
        if (err) reject(err);
        resolve(deletedCount === 1); // Resolve based on successful deletion
      });
    });
  }
}

// Export an instance for use
const redisClient = new RedisClient(); 
module.exports = redisClient;
