import (
	"fmt"
	"strings"
)

func detectDoubleNegative(sentence string) {
	// 1. Define a slice of common negative words to watch for in double negatives
	negativeWords := []string{"not", "never", "rarely", "scarcely", "hardly", "no", "none"}

	// 2. Tokenize the sentence into words for easier analysis
	words := strings.Fields(sentence)

	// 3. Iterate through the tokens, checking for the pattern: "not" + negativeWord
	for i := range words {
