```powershell
# Function to recursively check folder ACLs and SIDHistory for domain users/groups
function Check-RecursiveACLs {
    param(
        [string]$FolderPath,
        [string]$DomainName = (Get-ADDomainController).Name # Default to current domain
    )

    # Get all users and groups in the domain and build a SIDHistory dictionary
    $SIDsInHistory = @{}
    Get-ADUser -Filter * -Properties SamAccountName,SIDHistory | ForEach-Object {
        $SamAccountName = $_.SamAccountName
        $SIDsInHistory[$SamAccountName] = $_.SIDHistory -split ';'
    }
    Get-ADGroup -Filter * -Properties MemberOf,SIDHistory | ForEach-Object {
        $GroupName = $_.Name
        $SIDsInHistory[$GroupName] = $_.SIDHistory -split ';'
    }

    # Recursive function to process folders and their ACLs
    function Process-Folder {
        param(
            [string]$CurrentFolder
        )
        # Get ACLs for the folder
        $Acl = Get-Acl -Path $CurrentFolder

        # Iterate through Access Control Entries (ACEs)
        foreach ($Ace in $Acl.Access) {
            if ($Ace.IdentityReference -isnot [null]) {
                $Sid = $Ace.IdentityReference.Translate([System.Security.Principal.NTAccount], $DomainName).Value
                # Check if SID exists ONLY in recorded SIDHistory entries
                if (!(($SIDsInHistory.Keys | Where-Object { $_ -match $Sid }) -ne $null)) {
                    Write-Warning "WARNING: ACL SID '$Sid' in folder '$CurrentFolder' not found in explicit SIDHistory of any domain user/group."
                    # Optionally log this discrepancy to a file for further analysis
                    # Write-Output "$CurrentFolder,$Sid" >> "ACL_SIDDiscrepancy.log" 
                }
            }
        }

        # Recursively process subfolders
        Get-ChildItem -Path $CurrentFolder -Recurse | Where-Object {$_.PSIsContainer} | ForEach-Object { Process-Folder -CurrentFolder $_.FullName }
    }

    # Start recursive processing from the provided folder path
    Process-Folder -CurrentFolder $FolderPath
}

