        [Parameter(Mandatory=$true)]
        [string]$FolderPath,
        [string]$DomainController = (Get-ADDomainController).Name # Default to current domain controller
    )

    # Get all users and groups in the domain for SIDHistory comparison
    $DomainUsersAndGroups = Get-ADUser -Filter * -Properties SamAccountName,SidHistory -Server $DomainController | ForEach-Object { $_.SamAccountName, $_.SidHistory }
    $DomainUsersAndGroups += Get-ADGroup -Filter * -Properties SamAccountName,SidHistory -Server $DomainController | ForEach-Object { $_.SamAccountName, $_.SidHistory }

    # Recursive function to process folders and their subfolders
    function Process-Folder {
        param(
            [string]$CurrentFolder
        )
        # Get ACL entries for the current folder
        $ACLs = Get-Acl -Path $CurrentFolder

        foreach ($Entry in $ACLs.Access) {
            # Extract SIDs from ACL entries
            $ACLSid = $Entry.IdentityReference.Translate([System.Security.Principal.NTAccount])
            $ACLSid = $ACLSid.Translate([System.Security.Principal.SecurityIdentifier])

            # Check if the SID exists ONLY in any user/group's SidHistory within the domain
            $FoundInHistory = $false
            foreach ([string]$UserGroupName, $HistorySIDs in $DomainUsersAndGroups) {
                if ($HistorySIDs -contains $ACLSid) {
                    $FoundInHistory = $true
                    break  # Move to next ACL entry once found
                }
            }

            if (-not $FoundInHistory) {
                Write-Warning "WARNING: SID $($ACLSid.Value) in ACL of '$CurrentFolder' NOT found in any user/group's SidHistory on domain controller '$DomainController'"
            }
        }

        # Recursively process subfolders
        Get-ChildItem -Path $CurrentFolder -Recurse | ForEach-Object { Process-Folder -CurrentFolder $_.FullName }
    }

    # Start recursive processing from the provided folder path
    Process-Folder -CurrentFolder $FolderPath
}

